mapper.select:
${pagingTop} SELECT homepage_id, lecture_idx, event_name, event_start_date, event_end_date, event_place, event_start_time, event_end_time, apply_start_date, apply_start_time, apply_end_date, apply_end_time, recruitment_number, conrtents, org_file_name, server_file_name, file_extension, file_size, exposure_status, delete_yn, add_id, add_date, view_count, (select count(*) from RELAY_LECTURE_APPLY B where B.lecture_idx = A.lecture_idx and B.reception_status != 'N') as apply_count FROM RELAY_LECTURE A WHERE homepage_id = #{homepage_id} AND delete_yn = 'N'
AND ${search_type} LIKE '%'||#{search_text}||'%'
ORDER BY lecture_idx DESC ${pagingBottom}

${pagingTop} SELECT homepage_id, lecture_idx, event_name, event_start_date, event_end_date, event_place, event_start_time, event_end_time, apply_start_date, apply_start_time, apply_end_date, apply_end_time, recruitment_number, conrtents, org_file_name, server_file_name, file_extension, file_size, exposure_status, delete_yn, add_id, add_date, apply_status, (select count(*) from RELAY_LECTURE_APPLY B where B.lecture_idx = A.lecture_idx and B.reception_status != 'N') as apply_count FROM RELAY_LECTURE A WHERE homepage_id = #{homepage_id} AND delete_yn = 'N' AND exposure_status = 'Y'
AND ${search_type} LIKE '%'||#{search_text}||'%'
ORDER BY lecture_idx DESC ${pagingBottom}

mapper.update:
UPDATE RELAY_LECTURE SET event_name = #{event_name}, event_start_date = #{event_start_date}, event_end_date = #{event_end_date}, event_place = #{event_place}, event_start_time = #{event_start_time}, event_end_time = #{event_end_time}, apply_start_date = #{apply_start_date}, apply_start_time = #{apply_start_time}, apply_end_date = #{apply_end_date}, apply_end_time = #{apply_end_time}, recruitment_number = #{recruitment_number}, conrtents = #{conrtents},
org_file_name = #{org_file_name}, server_file_name = #{server_file_name}, file_extension = #{file_extension}, file_size = #{file_size},
exposure_status = #{exposure_status}, modify_id = #{modify_id}, modify_date = SYSDATE WHERE homepage_id = #{homepage_id} AND lecture_idx = #{lecture_idx}

UPDATE
	RELAY_LECTURE
SET
	delete_yn = 'Y',
	delete_id = #{delete_id}
WHERE
	homepage_id = #{homepage_id}
AND lecture_idx = #{lecture_idx}

UPDATE
	RELAY_LECTURE
SET
	exposure_status = #{exposure_status}
WHERE
	homepage_id = #{homepage_id}
AND lecture_idx = #{lecture_idx}
